  evidence=[f'{rel}:{next(i+1 for i,l in enumerate(lines) if l.startswith("objective:"))}',f'{rel}:{next(i+1 for i,l in enumerate(lines) if l.startswith("evaluation:"))}','critbench/evaluation/structured.py:153','critbench/evaluation/structured.py:205']
  if fam=='vm':evidence += ['critbench/tasksv2/vm/truth.py:44','critbench/tasksv2/vm/capture_baseline.py:76','critbench/docker/critbench_ied_server.c:323','critbench/docker/critbench_ied_server.c:504','critbench/docker/iec104_server.py:109']
